import { defineConfig } from 'vite';

export default defineConfig({
  root: 'client',
  build: {
    outDir: '../dist',
    emptyOutDir: true,
  },
});

import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

console.error('Starting server...');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());

// Initialize PGLite with filesystem persistence
const DATA_DIR = join(__dirname, '..', 'data');
console.error('Data dir:', DATA_DIR);
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  console.error('Created data directory');
}

const pglite = new PGlite({
  dataDir: DATA_DIR,
  relaxedDurability: true,
});

// SSE client tracking
const sseClients = [];

// Initialize database
async function initDatabase() {
  console.error('Initializing database...');
  await pglite.waitReady;
  console.error('PGLite ready');
  await pglite.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
    );
  `);
  console.error('Database initialized');
}

// Get historical messages
app.get('/api/messages', async (req, res) => {
  try {
    const result = await pglite.query(
      'SELECT id, text, created_at FROM messages ORDER BY created_at ASC'
    );
    const messages = result.rows.map((row) => ({
      id: row.id,
      text: row.text,
      created_at: row.created_at,
    }));
    res.json(messages);
  } catch (err) {
    console.error('Error fetching messages:', err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// SSE endpoint for real-time updates
app.get('/api/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
  });

  const client = res;
  sseClients.push(client);

  client.on('close', () => {
    const index = sseClients.indexOf(client);
    if (index !== -1) {
      sseClients.splice(index, 1);
    }
  });
});

// Broadcast a message to all SSE clients
function broadcastMessage(message) {
  const data = JSON.stringify(message);
  const payload = `data: ${data}\n\n`;
  sseClients.forEach((client) => {
    client.write(payload);
  });
}

// Post a new message
app.post('/api/messages', async (req, res) => {
  try {
    const { text } = req.body;

    if (!text || typeof text !== 'string' || text.trim() === '') {
      return res.status(400).json({ error: 'Message text is required' });
    }

    const result = await pglite.query(
      'INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at',
      [text.trim()]
    );

    const message = {
      id: result.rows[0].id,
      text: result.rows[0].text,
      created_at: result.rows[0].created_at,
    };

    // Broadcast to all SSE clients
    broadcastMessage(message);

    res.status(201).json(message);
  } catch (err) {
    console.error('Error posting message:', err);
    res.status(500).json({ error: 'Failed to post message' });
  }
});

// Start server
async function start() {
  try {
    await initDatabase();
    app.listen(PORT, () => {
      console.error(`Server running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

start();

const API_BASE = window.location.origin;

const messageList = document.getElementById('message-list');
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');

// Fetch historical messages on page load
async function loadMessages() {
  try {
    const response = await fetch(`${API_BASE}/api/messages`);
    if (!response.ok) throw new Error('Failed to fetch messages');
    const messages = await response.json();
    messages.forEach((msg) => appendMessage(msg));
  } catch (err) {
    console.error('Error loading messages:', err);
  }
}

// Append a message to the DOM
function appendMessage(msg) {
  const li = document.createElement('li');
  li.className = 'message-item';
  li.dataset.id = msg.id;

  const textDiv = document.createElement('div');
  textDiv.className = 'message-text';
  textDiv.textContent = msg.text;

  const timeSpan = document.createElement('span');
  timeSpan.className = 'message-time';
  timeSpan.textContent = new Date(msg.created_at).toLocaleString();

  li.appendChild(textDiv);
  li.appendChild(timeSpan);

  messageList.appendChild(li);

  // Scroll to bottom
  window.scrollTo(0, document.body.scrollHeight);
}

// Connect to SSE stream
function connectStream() {
  const eventSource = new EventSource(`${API_BASE}/api/stream`);

  eventSource.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    // Only append if not already in the DOM (to avoid duplicates on reconnect)
    const existing = messageList.querySelector(`[data-id="${msg.id}"]`);
    if (!existing) {
      appendMessage(msg);
    }
  });

  eventSource.onerror = (err) => {
    console.error('SSE connection error:', err);
    eventSource.close();
    // Reconnect after a delay
    setTimeout(connectStream, 3000);
  };
}

// Handle form submission
messageForm.addEventListener('submit', async (e) => {
  e.preventDefault();

  const text = messageInput.value.trim();
  if (!text) return;

  try {
    const response = await fetch(`${API_BASE}/api/messages`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ text }),
    });

    if (!response.ok) throw new Error('Failed to post message');

    // Clear input
    messageInput.value = '';
  } catch (err) {
    console.error('Error posting message:', err);
  }
});

// Initialize
loadMessages();
connectStream();

